<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EV Charging Network Performance &amp; Grid Optimization Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1e40af;
    --primary-light: #3b82f6;
    --primary-dark: #1e3a8a;
    --accent: #10b981;
    --accent-light: #34d399;
    --warning: #f59e0b;
    --danger: #ef4444;
    --neutral-50: #f8fafc;
    --neutral-100: #f1f5f9;
    --neutral-200: #e2e8f0;
    --neutral-300: #cbd5e1;
    --neutral-600: #475569;
    --neutral-700: #334155;
    --neutral-800: #1e293b;
    --neutral-900: #0f172a;
    --urban: #3b82f6;
    --highway: #f59e0b;
    --suburban: #10b981;
    --peak: #ef4444;
    --offpeak: #10b981;
    --midpeak: #f59e0b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--neutral-100);
    color: var(--neutral-800);
    line-height: 1.6;
  }

  /* ---- Header ---- */
  .report-header {
    background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 60%, var(--primary-light) 100%);
    color: white;
    padding: 48px 48px 40px;
    position: relative;
    overflow: hidden;
  }
  .report-header::after {
    content: '';
    position: absolute;
    right: -80px; top: -80px;
    width: 340px; height: 340px;
    border-radius: 50%;
    background: rgba(255,255,255,0.06);
  }
  .report-header::before {
    content: '';
    position: absolute;
    right: 60px; bottom: -60px;
    width: 220px; height: 220px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }
  .header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.3);
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 16px;
  }
  .report-header h1 {
    font-size: 2.1rem;
    font-weight: 700;
    line-height: 1.2;
    max-width: 700px;
    margin-bottom: 12px;
  }
  .report-header p {
    font-size: 1.0rem;
    opacity: 0.85;
    max-width: 620px;
    margin-bottom: 20px;
  }
  .header-meta {
    display: flex;
    gap: 24px;
    font-size: 0.82rem;
    opacity: 0.75;
  }
  .header-meta span { display: flex; align-items: center; gap: 6px; }

  /* ---- Nav ---- */
  .nav-bar {
    background: white;
    border-bottom: 1px solid var(--neutral-200);
    padding: 0 48px;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  }
  .nav-bar ul {
    display: flex;
    gap: 0;
    list-style: none;
    overflow-x: auto;
  }
  .nav-bar a {
    display: block;
    padding: 14px 16px;
    font-size: 0.82rem;
    font-weight: 500;
    color: var(--neutral-600);
    text-decoration: none;
    border-bottom: 2px solid transparent;
    white-space: nowrap;
    transition: all 0.15s;
  }
  .nav-bar a:hover { color: var(--primary); border-color: var(--primary-light); }

  /* ---- Container ---- */
  .container { max-width: 1280px; margin: 0 auto; padding: 40px 48px; }

  /* ---- KPI Banner ---- */
  .kpi-banner {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: white;
    border-radius: 12px;
    padding: 22px 20px;
    border: 1px solid var(--neutral-200);
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
    transition: box-shadow 0.2s;
  }
  .kpi-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.1); }
  .kpi-label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--neutral-600);
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: var(--primary);
    line-height: 1;
    margin-bottom: 4px;
  }
  .kpi-sub {
    font-size: 0.75rem;
    color: var(--neutral-600);
  }
  .kpi-card.accent .kpi-value { color: var(--accent); }
  .kpi-card.warning .kpi-value { color: var(--warning); }
  .kpi-card.danger .kpi-value { color: var(--danger); }

  /* ---- Section ---- */
  .section {
    background: white;
    border-radius: 14px;
    border: 1px solid var(--neutral-200);
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
    margin-bottom: 32px;
    overflow: hidden;
  }
  .section-header {
    padding: 24px 28px 20px;
    border-bottom: 1px solid var(--neutral-100);
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .section-icon {
    width: 40px; height: 40px;
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.2rem;
    flex-shrink: 0;
