  .icon-blue { background: #eff6ff; }
  .icon-amber { background: #fffbeb; }
  .icon-green { background: #ecfdf5; }
  .icon-purple { background: #f5f3ff; }
  .icon-rose { background: #fff1f2; }
  .icon-teal { background: #f0fdfa; }
  .section-title { font-size: 1.15rem; font-weight: 700; color: var(--neutral-800); margin-bottom: 4px; }
  .section-subtitle { font-size: 0.82rem; color: var(--neutral-600); }
  .section-body { padding: 24px 28px; }

  /* ---- Charts grid ---- */
  .chart-grid { display: grid; gap: 24px; }
  .chart-grid-2 { grid-template-columns: 1fr 1fr; }
  .chart-grid-3 { grid-template-columns: 1fr 1fr 1fr; }
  .chart-card {
    background: var(--neutral-50);
    border-radius: 10px;
    border: 1px solid var(--neutral-200);
    padding: 20px;
  }
  .chart-card.full { grid-column: 1 / -1; }
  .chart-title {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--neutral-700);
    margin-bottom: 16px;
  }
  .chart-container { position: relative; }

  /* ---- Heatmap ---- */
  .heatmap-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.82rem;
  }
  .heatmap-table th {
    padding: 8px 12px;
    text-align: center;
    font-weight: 600;
    color: var(--neutral-700);
    background: var(--neutral-100);
    border: 1px solid var(--neutral-200);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .heatmap-table th.row-header { text-align: left; }
  .heatmap-table td {
    padding: 10px 12px;
    text-align: center;
    border: 1px solid var(--neutral-200);
    font-weight: 600;
    font-size: 0.88rem;
  }
  .heatmap-table td.row-label {
    text-align: left;
    font-weight: 600;
    color: var(--neutral-700);
    background: var(--neutral-100);
    font-size: 0.82rem;
  }

  /* ---- Insights ---- */
  .insights-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px; margin-top: 22px; }
  .insight-card {
    border-radius: 8px;
    padding: 14px 16px;
    border-left: 3px solid;
  }
  .insight-card.blue { background: #eff6ff; border-color: var(--primary-light); }
  .insight-card.green { background: #ecfdf5; border-color: var(--accent); }
  .insight-card.amber { background: #fffbeb; border-color: var(--warning); }
  .insight-card.red { background: #fff1f2; border-color: var(--danger); }
  .insight-card.purple { background: #f5f3ff; border-color: #8b5cf6; }
  .insight-title { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 5px; color: var(--neutral-700); }
  .insight-text { font-size: 0.82rem; color: var(--neutral-700); line-height: 1.4; }

  /* ---- Tables ---- */
  .data-table { width: 100%; border-collapse: collapse; font-size: 0.84rem; }
  .data-table thead th {
    background: var(--neutral-100);
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    color: var(--neutral-700);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-bottom: 2px solid var(--neutral-200);
  }
  .data-table tbody td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--neutral-100);
    color: var(--neutral-700);
  }
  .data-table tbody tr:hover { background: var(--neutral-50); }
  .badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 20px;
    font-size: 0.72rem;
    font-weight: 600;
  }
  .badge-blue { background: #dbeafe; color: #1e40af; }
  .badge-amber { background: #fef3c7; color: #92400e; }
  .badge-green { background: #d1fae5; color: #065f46; }
  .badge-red { background: #fee2e2; color: #991b1b; }
  .badge-purple { background: #ede9fe; color: #5b21b6; }

  /* ---- Recommendations ---- */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
  .rec-card {
    border-radius: 10px;
    padding: 20px;
    border: 1px solid;
  }
  .rec-card.priority-high { background: #fff1f2; border-color: #fecaca; }
  .rec-card.priority-medium { background: #fffbeb; border-color: #fde68a; }
  .rec-card.priority-low { background: #ecfdf5; border-color: #a7f3d0; }
  .rec-header { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
  .rec-num {
    width: 28px; height: 28px;
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.78rem;
    font-weight: 700;
    flex-shrink: 0;
  }
  .rec-num.high { background: #ef4444; color: white; }
  .rec-num.medium { background: var(--warning); color: white; }
  .rec-num.low { background: var(--accent); color: white; }
  .rec-title { font-size: 0.92rem; font-weight: 700; color: var(--neutral-800); }
  .rec-body { font-size: 0.82rem; color: var(--neutral-700); line-height: 1.5; }
  .rec-metric { font-size: 0.78rem; font-weight: 600; margin-top: 8px; padding: 5px 10px; background: rgba(255,255,255,0.7); border-radius: 6px; display: inline-block; }

  /* ---- Footer ---- */
  .report-footer {
    background: var(--neutral-800);
    color: var(--neutral-300);
    padding: 28px 48px;
    font-size: 0.8rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  /* ---- Divider ---- */
  .divider { border: none; border-top: 1px solid var(--neutral-200); margin: 22px 0; }

  /* ---- Stat row ---- */
  .stat-row { display: flex; gap: 24px; flex-wrap: wrap; margin-top: 16px; }
  .stat-item { text-align: center; }
  .stat-item .val { font-size: 1.4rem; font-weight: 700; color: var(--primary); }
  .stat-item .lbl { font-size: 0.72rem; color: var(--neutral-600); text-transform: uppercase; letter-spacing: 0.05em; }

  @media (max-width: 900px) {
    .kpi-banner { grid-template-columns: repeat(3, 1fr); }
