<body>

<!-- ===== HEADER ===== -->
<div class="report-header">
  <div class="header-badge">Analytics Report</div>
  <h1>EV Charging Network Performance &amp; Grid Optimization</h1>
  <p>A comprehensive analysis of charging station operations, demand patterns, grid load dynamics, and optimization opportunities across a smart-grid charging network of 20 stations.</p>
  <div class="header-meta">
    <span>&#128197; April 2025</span>
    <span>&#128202; 8,354 Sessions Analyzed</span>
    <span>&#127963; 20 Stations</span>
    <span>&#128101; Audience: Infrastructure &amp; Grid Management</span>
  </div>
</div>

<!-- ===== NAV ===== -->
<nav class="nav-bar">
  <ul>
    <li><a href="#kpis">KPI Summary</a></li>
    <li><a href="#utilization">Station Utilization</a></li>
    <li><a href="#queue">Queue &amp; Wait Times</a></li>
    <li><a href="#energy">Energy &amp; Grid Load</a></li>
    <li><a href="#renewable">Renewable &amp; Pricing</a></li>
    <li><a href="#vehicles">Vehicle Profiles</a></li>
    <li><a href="#recommendations">Recommendations</a></li>
  </ul>
</nav>

<!-- ===== MAIN ===== -->
<div class="container">

  <!-- ===== KPI BANNER ===== -->
  <div id="kpis" class="kpi-banner">
    <div class="kpi-card">
      <div class="kpi-label">Avg Waiting Time</div>
      <div class="kpi-value">9.53</div>
      <div class="kpi-sub">minutes per session</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg Energy / Session</div>
      <div class="kpi-value">39.08</div>
      <div class="kpi-sub">kWh consumed</div>
    </div>
    <div class="kpi-card warning">
      <div class="kpi-label">Mean Station Load</div>
      <div class="kpi-value">53.18</div>
      <div class="kpi-sub">kW average grid draw</div>
    </div>
    <div class="kpi-card accent">
      <div class="kpi-label">Renewable Energy Ratio</div>
      <div class="kpi-value">35.4%</div>
      <div class="kpi-sub">avg green energy share</div>
    </div>
    <div class="kpi-card danger">
      <div class="kpi-label">Mean Optimization Reward</div>
      <div class="kpi-value">−11.83</div>
      <div class="kpi-sub">composite grid performance score</div>
    </div>
  </div>

  <!-- ===== SECTION 1: STATION UTILIZATION ===== -->
  <div id="utilization" class="section">
    <div class="section-header">
      <div class="section-icon icon-blue">&#128267;</div>
      <div>
        <div class="section-title">1 &mdash; Station Utilization &amp; Demand Analysis</div>
        <div class="section-subtitle">Charging demand distribution across stations and location types; high-demand periods and capacity signals</div>
      </div>
    </div>
    <div class="section-body">

      <div class="chart-grid chart-grid-2">
        <div class="chart-card">
          <div class="chart-title">Sessions by Location Type</div>
          <div class="chart-container" style="height:220px">
            <canvas id="chartLocSessions"></canvas>
          </div>
        </div>
        <div class="chart-card">
          <div class="chart-title">Charging Demand: Peak vs Off-Peak by Location</div>
          <div class="chart-container" style="height:220px">
            <canvas id="chartDemandSlot"></canvas>
          </div>
        </div>
        <div class="chart-card full">
          <div class="chart-title">Session Volume by Day of Week</div>
          <div class="chart-container" style="height:200px">
            <canvas id="chartDOW"></canvas>
          </div>
        </div>
      </div>

      <!-- Demand heatmap -->
      <div style="margin-top:24px">
        <div class="chart-title">Average Charging Demand: Location × Time Slot</div>
        <table class="heatmap-table" style="max-width:480px">
          <thead>
            <tr>
              <th class="row-header">Location</th>
              <th>Off-Peak</th>
              <th>Peak</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td class="row-label">Highway</td>
              <td style="background:rgba(59,130,246,0.18)">34.68</td>
              <td style="background:rgba(239,68,68,0.45)">84.04</td>
            </tr>
            <tr>
              <td class="row-label">Urban</td>
              <td style="background:rgba(59,130,246,0.18)">34.52</td>
              <td style="background:rgba(239,68,68,0.46)">84.14</td>
            </tr>
          </tbody>
        </table>
        <p style="font-size:0.75rem;color:var(--neutral-600);margin-top:8px">Values represent mean charging demand score. Peak periods show 2.4× the demand intensity of off-peak windows.</p>
